export type Equipment = {
  id: number;
  name: string;
  zone: string;
  labels: string[];
};

export type EquipmentInput = Omit<Equipment, "id">;

function normalize(input: EquipmentInput): EquipmentInput {
  if (typeof input !== "object" || input === null) throw new TypeError("Invalid equipment");
  if (typeof input.name !== "string" || input.name.trim() === "" ||
      typeof input.zone !== "string" || input.zone.trim() === "" ||
      !Array.isArray(input.labels) || input.labels.some(label => typeof label !== "string")) {
    throw new TypeError("Invalid equipment");
  }
  return { name: input.name.trim(), zone: input.zone.trim(), labels: [...input.labels] };
}

function copy(item: Equipment): Equipment {
  return { ...item, labels: [...item.labels] };
}

export class EquipmentCatalog {
  private readonly accessKey: string;
  private readonly items: Equipment[] = [];
  private nextId = 1;

  constructor(accessKey: string) {
    if (typeof accessKey !== "string" || accessKey.length === 0) throw new TypeError("Invalid key");
    this.accessKey = accessKey;
  }

  private authorize(key: string): void {
    if (key !== this.accessKey) throw new Error("Unauthorized");
  }

  list(): Equipment[] {
    return this.items.map(copy);
  }

  add(accessKey: string, input: EquipmentInput): Equipment {
    this.authorize(accessKey);
    const item: Equipment = { id: this.nextId++, ...normalize(input) };
    this.items.push(item);
    return copy(item);
  }

  replace(accessKey: string, id: number, input: EquipmentInput): Equipment {
    this.authorize(accessKey);
    if (!Number.isInteger(id) || id <= 0) throw new RangeError("Invalid id");
    const index = this.items.findIndex(item => item.id === id);
    if (index < 0) throw new RangeError("Equipment not found");
    const item: Equipment = { id, ...normalize(input) };
    this.items[index] = item;
    return copy(item);
  }

  remove(accessKey: string, id: number): boolean {
    if (!Number.isInteger(id) || id <= 0) throw new RangeError("Invalid id");
    const index = this.items.findIndex(item => item.id === id);
    if (index < 0) return false;
    this.items.splice(index, 1);
    return true;
  }
}

