import { EquipmentCatalog, type EquipmentInput } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}

function captures(fn: () => unknown): unknown {
  try {
    fn();
  } catch (error) {
    return error;
  }
  return undefined;
}

function assertUnauthorized(error: unknown, message: string): void {
  assert(error instanceof Error && error.message === 'Unauthorized', message);
}

assert(captures(() => new EquipmentCatalog('')) instanceof TypeError, 'empty access key rejected');

const catalog = new EquipmentCatalog('key');
assert(catalog.list().length === 0, 'new catalog is empty');

const input: EquipmentInput = {
  name: '  Pump  ',
  zone: ' West ',
  labels: [' critical ', 'critical', '']
};
const first = catalog.add('key', input);
deepEqual(
  first,
  { id: 1, name: 'Pump', zone: 'West', labels: [' critical ', 'critical', ''] },
  'add trims fields and preserves labels unchanged and in order'
);

input.name = 'Mutated';
input.zone = 'Mutated';
input.labels[0] = 'changed';
deepEqual(
  catalog.list()[0],
  { id: 1, name: 'Pump', zone: 'West', labels: [' critical ', 'critical', ''] },
  'add copies its input'
);

first.name = 'Changed';
first.zone = 'Changed';
first.labels.push('new');
deepEqual(
  catalog.list()[0],
  { id: 1, name: 'Pump', zone: 'West', labels: [' critical ', 'critical', ''] },
  'add result is defensive'
);

const second = catalog.add('key', { name: 'Valve', zone: 'East', labels: [] });
assert(second.id === 2, 'ids increase');
deepEqual(catalog.list().map(item => item.id), [1, 2], 'list preserves insertion order');

const replacementInput: EquipmentInput = {
  name: ' New Pump ',
  zone: ' North ',
  labels: ['blue']
};
const replaced = catalog.replace('key', 1, replacementInput);
deepEqual(
  replaced,
  { id: 1, name: 'New Pump', zone: 'North', labels: ['blue'] },
  'replace trims fields and preserves id'
);
replacementInput.name = 'Mutated';
replacementInput.labels[0] = 'changed';
replaced.name = 'Changed';
replaced.labels[0] = 'also changed';
deepEqual(catalog.list().map(item => item.id), [1, 2], 'replace preserves list position');
deepEqual(
  catalog.list()[0],
  { id: 1, name: 'New Pump', zone: 'North', labels: ['blue'] },
  'replace copies its input and result'
);

const listed = catalog.list();
listed.reverse();
listed[0].name = 'Bad';
listed[0].labels.push('bad');
deepEqual(catalog.list().map(item => item.id), [1, 2], 'list array is defensive');
deepEqual(catalog.list()[1], { id: 2, name: 'Valve', zone: 'East', labels: [] }, 'listed items are defensive');

assert(catalog.remove('key', 99) === false, 'absent valid removal returns false');
assert(catalog.remove('key', 1) === true, 'existing item is removed');
deepEqual(catalog.list().map(item => item.id), [2], 'removal updates the catalog');
assert(
  catalog.add('key', { name: 'Sensor', zone: 'Lab', labels: ['x'] }).id === 3,
  'removed ids are not reused'
);

for (const badId of [0, -1, 1.5, NaN, Infinity]) {
  assert(
    captures(() => catalog.replace('key', badId, { name: 'X', zone: 'Y', labels: [] })) instanceof RangeError,
    'replace rejects a non-positive-integer id with RangeError'
  );
}
assert(
  captures(() => catalog.replace('key', 500, { name: 'X', zone: 'Y', labels: [] })) instanceof RangeError,
  'replace rejects a missing id with RangeError'
);

const malformedInputs: unknown[] = [
  { name: '   ', zone: 'Z', labels: [] },
  { name: 'X', zone: '', labels: [] },
  { name: 4, zone: 'Z', labels: [] },
  { name: 'X', zone: null, labels: [] },
  { name: 'X', zone: 'Z', labels: 'bad' },
  { name: 'X', zone: 'Z', labels: ['ok', 4] },
  null
];
for (const badInput of malformedInputs) {
  assert(
    captures(() => catalog.add('key', badInput as EquipmentInput)) !== undefined,
    'malformed input is rejected'
  );
}

const beforeFailures = catalog.list();
assertUnauthorized(
  captures(() => catalog.add('wrong', null as unknown as EquipmentInput)),
  'add authorization precedes input validation'
);
assertUnauthorized(
  captures(() => catalog.replace('wrong', 0, null as unknown as EquipmentInput)),
  'replace authorization precedes id and input validation'
);
assertUnauthorized(
  captures(() => catalog.remove('wrong', NaN)),
  'remove authorization precedes id inspection'
);
deepEqual(catalog.list(), beforeFailures, 'failed operations leave state unchanged');

